package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true"}) @ActiveProfiles("test") @Transactional
class PhaseN3CalendarTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerCalendar calendar;PhaseIFixtures.Actor member,listener,staff;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);}
 void clock(String at){Instant.parse(at);db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+at+"'::timestamptz $$");}
 @Test @Tag("creative") void bothRepeatedHoursGenerateSeparateGenuineHalfHours(){clock("2026-10-26T00:00:00Z");calendar.rule(listener.id(),null,new ListenerCalendar.Rule("America/Los_Angeles",7,LocalTime.of(1,0),LocalTime.of(1,30),LocalDate.parse("2026-10-26"),LocalDate.parse("2026-11-02"),"BOTH",0));var slots=calendar.slots(member.id(),listener.id(),50,null).items();assertThat(slots.stream().map(ListenerCalendar.Slot::startsAt)).contains(Instant.parse("2026-11-01T08:00:00Z"),Instant.parse("2026-11-01T09:00:00Z"));assertThat(slots).allMatch(s->s.startsAt().atZone(ZoneId.of(s.timezone())).toLocalTime().equals(LocalTime.of(1,0)));}
 @Test @Tag("creative") void nonexistentWeeklyBoundaryIsSkippedRatherThanShifted(){clock("2027-03-01T00:00:00Z");calendar.rule(listener.id(),null,new ListenerCalendar.Rule("America/Los_Angeles",7,LocalTime.of(2,30),LocalTime.of(4,0),LocalDate.parse("2027-03-01"),LocalDate.parse("2027-03-15"),"EARLIER",0));assertThat(calendar.slots(member.id(),listener.id(),50,null).items()).noneMatch(s->s.startsAt().atZone(ZoneId.of(s.timezone())).toLocalDate().equals(LocalDate.parse("2027-03-14")));}
 @Test @Tag("creative") void overnightRuleBelongsToItsStartingLocalWeekday(){clock("2026-10-26T00:00:00Z");calendar.rule(listener.id(),null,new ListenerCalendar.Rule("UTC",1,LocalTime.of(23,0),LocalTime.of(1,0),LocalDate.parse("2026-10-26"),LocalDate.parse("2026-11-02"),"EARLIER",0));assertThat(calendar.slots(member.id(),listener.id(),50,null).items().stream().map(ListenerCalendar.Slot::startsAt)).contains(Instant.parse("2026-10-27T00:20:00Z"));}
}
